INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 19, 'theory', 'Квиз: NFS, loop-устройства и qemu-img');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 0, 'В /etc/exports для каталога /data записаны две записи: «*.lab.example.com(rw)» и «10.0.0.0/24(ro)». Клиент web1.lab.example.com имеет адрес 10.0.0.5. Какой доступ он получит?', '["Чтение и запись: шаблон стоит первым в файле", "Только чтение: сеть точнее шаблона, порядок строк не важен", "Никакого: две подходящие записи конфликтуют", "Чтение и запись: из двух побеждает более широкий доступ"]', 1, 'Если клиент подходит под несколько записей, действует более точная: хост, затем сеть, затем шаблон, затем группа, затем звёздочка. Порядок строк не учитывается, конфликта нет.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 1, 'Экспорт настроен как «rw,root_squash,anonuid=36». Клиент под root (uid 0) создаёт на нём файл. Какой uid будет у файла на сервере?', '["0: root всегда остаётся root", "65534: так сказано в странице руководства для всех экспортов", "36: запросы root превращаются в anonuid", "Файл не создастся, root_squash запрещает запись"]', 2, 'root_squash отображает запросы uid 0 на анонимного пользователя; число 65534 — лишь значение по умолчанию, а anonuid=36 его заменяет. Запись остаётся разрешённой, если у этого пользователя есть права на каталог.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 2, 'Сервер NFS недоступен десять минут. Клиент смонтирован с опциями по умолчанию (hard). Что произойдёт с программой, которая в это время пишет в файл?', '["Через retrans повторов она получит EIO", "Монтирование само переключится на soft", "Она получит ESTALE и должна открыть файл заново", "Она будет ждать и продолжит работу, когда сервер вернётся"]', 3, 'При hard запрос повторяется бесконечно: программа блокируется, а ядро пишет «not responding, still trying», затем «OK». Ошибку EIO даёт soft, ESTALE — другой случай, когда дескриптор перестал существовать на сервере.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 3, 'Образ top.qcow2 ссылается на base.qcow2. Что делает «qemu-img commit top.qcow2»?', '["Записывает выделенные кластеры top в base, после чего top пуст, но связан с base", "Копирует base в top и обрывает ссылку", "Только проверяет согласованность цепочки", "Удаляет base и переносит данные в top"]', 0, 'commit сливает изменения слоя вниз, в его backing, и по умолчанию оставляет слой пустым (флаг -d сохраняет его содержимое). База при необходимости вырастает.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 19, 4, '«ls -l» показывает disk.img размером 10 ГиБ, а «du -h disk.img» печатает 0. Что это значит?', '["Файл повреждён: размер и занятое место должны совпадать", "Файл разреженный: блоки выделяются только под записанное, остальное — дыры", "Файл сжат файловой системой", "Файл подключён к loop-устройству и du его не видит"]', 1, 'Длина файла и число выделенных блоков (st_blocks, в единицах по 512 байт) независимы. У файла, созданного truncate, дыры читаются нулями и места не занимают, пока в них ничего не записано.');
